class CircuitOpenError < StandardError; end

class CircuitBreaker
  def initialize(failure_threshold, reset_timeout)
    @failure_threshold = failure_threshold
    @reset_timeout = reset_timeout
    @state = :closed
    @failures = 0
    @opened_at = nil
  end

  def call(now, &block)
    if @state == :open
      raise CircuitOpenError if now - @opened_at < @reset_timeout
      @state = :half_open
    end

    begin
      result = block.call
    rescue StandardError => e
      if @state == :half_open
        @state = :open
        @opened_at = now
      else
        @failures += 1
        if @failures >= @failure_threshold
          @state = :open
          @opened_at = now
        end
      end
      raise e
    end

    @state = :closed
    @failures = 0
    result
  end
end

