require "minitest/autorun"
require_relative "breaker"

class CircuitBreakerTest < Minitest::Test
  def boom
    raise "boom"
  end

  def test_trips_open_after_consecutive_failures
    b = CircuitBreaker.new(3, 10)
    3.times do
      assert_raises(RuntimeError) { b.call(0) { boom } }
    end
    assert_raises(CircuitOpenError) { b.call(0) { "should not run" } }
  end

  def test_fails_fast_without_calling_block_while_open
    b = CircuitBreaker.new(1, 100)
    assert_raises(RuntimeError) { b.call(0) { boom } }
    called = false
    assert_raises(CircuitOpenError) { b.call(1) { called = true; "x" } }
    refute called
  end

  def test_half_open_trial_after_timeout_success_closes
    b = CircuitBreaker.new(1, 10)
    assert_raises(RuntimeError) { b.call(0) { boom } }
    assert_equal "ok", b.call(10) { "ok" }
    assert_equal "still-fine", b.call(11) { "still-fine" }
  end

  def test_half_open_failure_reopens_and_resets_clock
    b = CircuitBreaker.new(1, 10)
    assert_raises(RuntimeError) { b.call(0) { boom } }
    assert_raises(RuntimeError) { b.call(10) { boom } }
    assert_raises(CircuitOpenError) { b.call(15) { "too soon" } }
    assert_equal "ok now", b.call(20) { "ok now" }
  end
end
